/**
 * Ticket bodies become rich text (sanitized HTML). Converts existing plain-text bodies to HTML.
 * System replies stay plain text (they are generated by the application and escaped on output).
 */
class Migration_HelpdeskRichText extends CI_Migration {

    public function up()
    {
        foreach ($this->db->select('id, body')->get('tickets')->result() as $row) {
            $this->db->update('tickets', ['body' => $this->toHtml($row->body)], ['id' => $row->id]);
        }
        $replies = $this->db->select('id, body')->where('author_type !=', 'system')->where('body !=', '')->get('ticket_replies')->result();
        foreach ($replies as $row) {
            $this->db->update('ticket_replies', ['body' => $this->toHtml($row->body)], ['id' => $row->id]);
        }
    }

    public function down()
    {
        foreach ($this->db->select('id, body')->get('tickets')->result() as $row) {
            $this->db->update('tickets', ['body' => $this->toText($row->body)], ['id' => $row->id]);
        }
        $replies = $this->db->select('id, body')->where('author_type !=', 'system')->where('body !=', '')->get('ticket_replies')->result();
        foreach ($replies as $row) {
            $this->db->update('ticket_replies', ['body' => $this->toText($row->body)], ['id' => $row->id]);
        }
