    /** Same conversion as Tickets_model::textToHtml (kept inline so the migration doesn't depend on the model). */
    private function toHtml($text)
    {
        $html = htmlspecialchars((string) $text, ENT_QUOTES, 'UTF-8');
        $html = preg_replace('~(https?://[^\s<]+)~i', '<a href="$1" target="_blank" rel="noopener noreferrer nofollow">$1</a>', $html);
        return nl2br($html);
    }

    private function toText($html)
    {
        $text = preg_replace('~<br\s*/?>\s*~i', "\n", (string) $html);
        $text = preg_replace('~</(p|div|li|h[1-6]|blockquote|pre)>~i', "\n", $text);
        return trim(html_entity_decode(strip_tags($text), ENT_QUOTES, 'UTF-8'));
    }
}
